/* QR Gusaniza - local QR adapter
   Uses QRServer's image endpoint. This file is intentionally local so index.html
   does not depend on a JavaScript CDN.
*/
(function (global) {
  'use strict';
  function buildUrl(text, options) {
    options = options || {};
    var size = options.width || 1000;
    var ecc = options.errorCorrectionLevel || 'H';
    var margin = options.margin == null ? 4 : options.margin;
    return 'https://api.qrserver.com/v1/create-qr-code/?size=' + encodeURIComponent(size + 'x' + size) +
      '&qzone=' + encodeURIComponent(margin) +
      '&ecc=' + encodeURIComponent(ecc) +
      '&format=png&data=' + encodeURIComponent(text);
  }
  function toDataURL(text, options) {
    return Promise.resolve(buildUrl(text, options));
  }
  function toCanvas(canvas, text, options, callback) {
    if (typeof options === 'function') { callback = options; options = {}; }
    var img = new Image();
    img.onload = function () {
      canvas.width = options && options.width || 1000;
      canvas.height = options && options.width || 1000;
      var ctx = canvas.getContext('2d');
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      if (callback) callback(null);
    };
    img.onerror = function () {
      if (callback) callback(new Error('No se pudo obtener el QR desde el servicio de generación.'));
    };
    img.src = buildUrl(text, options);
  }
  global.QRCode = { toDataURL: toDataURL, toCanvas: toCanvas, _buildUrl: buildUrl };
})(window);
